        },
        {
          "find": "    def __init__(self, itemnum: int, hidden_units: int = 64, num_blocks: int = 2,",
          "replace": "    def __init__(self, itemnum: int, hidden_units: int = 64, num_blocks: int = 1,"
        }
      ]
    }
  ],
  "change_summary": "Set default SASRec depth to one block across all four category models, preserving metadata-driven predictor loading and the 200-epoch cap."
